select.where:
and t.ticket_no = #{ticketNo}
and t.ticket_category = #{ticketCategory}
and t.priority = #{priority}
and t.status = #{status}
and t.source = #{source}
and t.assigned_group = #{assignedGroup}
and t.assigned_user_id = #{assignedUserId}
and t.dead_line = #{deadLine}
and t.resolved_time = #{resolvedTime}
and t.closed_time = #{closedTime}
and t.user_id = #{userId}
and t.conversation_id = #{conversationId}
and t.create_time >= #{createTimeStart}
and t.create_time <= #{createTimeEnd}
and deleted = 0
